#include <iostream>
#include <array>
#include <vector>

constexpr int N = 9;

using Grid = std::array<std::array<int, N>, N>;

void printGrid(const Grid& grid, const std::string& title) {
    std::cout << "\n=== " << title << " ===\n";
    std::cout << "+-------+-------+-------+\n";
    for (int r = 0; r < N; ++r) {
        if (r % 3 == 0 && r != 0) {
            std::cout << "+-------+-------+-------+\n";
        }
        std::cout << "| ";
        for (int c = 0; c < N; ++c) {
            if (c % 3 == 0 && c != 0) {
                std::cout << "| ";
            }
            if (grid[r][c] == 0) {
                std::cout << ". ";
            } else {
                std::cout << grid[r][c] << " ";
            }
        }
        std::cout << "|\n";
    }
    std::cout << "+-------+-------+-------+\n";
}

bool isValid(const Grid& grid, int row, int col, int num) {
    for (int x = 0; x < N; ++x) {
        if (grid[row][x] == num) return false;
        if (grid[x][col] == num) return false;
    }
    int startRow = row - row % 3;
    int startCol = col - col % 3;
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            if (grid[startRow + i][startCol + j] == num) return false;
        }
    }
    return true;
}

bool findEmpty(const Grid& grid, int& row, int& col) {
    for (row = 0; row < N; ++row) {
        for (col = 0; col < N; ++col) {
            if (grid[row][col] == 0) return true;
        }
    }
    return false;
}

bool solveSudoku(Grid& grid) {
    int row, col;
    if (!findEmpty(grid, row, col)) return true;

    for (int num = 1; num <= 9; ++num) {
        if (isValid(grid, row, col, num)) {
            grid[row][col] = num;
            if (solveSudoku(grid)) return true;
            grid[row][col] = 0;
        }
    }
    return false;
}

int main() {
    Grid puzzle = {{
        {5, 3, 0, 0, 7, 0, 0, 0, 0},
        {6, 0, 0, 1, 9, 5, 0, 0, 0},
        {0, 9, 8, 0, 0, 0, 0, 6, 0},
        {8, 0, 0, 0, 6, 0, 0, 0, 3},
        {4, 0, 0, 8, 0, 3, 0, 0, 1},
        {7, 0, 0, 0, 2, 0, 0, 0, 6},
        {0, 6, 0, 0, 0, 0, 2, 8, 0},
        {0, 0, 0, 4, 1, 9, 0, 0, 5},
        {0, 0, 0, 0, 8, 0, 0, 7, 9}
    }};

    printGrid(puzzle, "START SUDOKU");

    Grid solution = puzzle;
    if (solveSudoku(solution)) {
        printGrid(solution, "SOLVED SUDOKU");
    } else {
        std::cout << "No solution exists!\n";
    }

    return 0;
}

