#include "Sudoku.h"
#include <iostream>

Sudoku::Sudoku() : grid_{}, solution_{}, solved_(false) {
    grid_.fill({});
    solution_.fill({});
}

Sudoku::Sudoku(const Grid& initialGrid) : grid_(initialGrid), solution_(initialGrid), solved_(false) {}

void Sudoku::setGrid(const Grid& grid) {
    grid_ = grid;
    solution_ = grid;
    solved_ = false;
}

Sudoku::Grid Sudoku::getGrid() const {
    return grid_;
}

Sudoku::Grid Sudoku::getSolution() const {
    return solution_;
}

bool Sudoku::solve() {
    solution_ = grid_;
    solved_ = solveRecursive(solution_);
    return solved_;
}

bool Sudoku::isSolved() const {
    return solved_;
}

void Sudoku::printGrid(const std::string& title) const {
    std::cout << "\n=== " << title << " ===\n";
    std::cout << "+-------+-------+-------+\n";
    for (int r = 0; r < N; ++r) {
        if (r % 3 == 0 && r != 0) {
            std::cout << "+-------+-------+-------+\n";
        }
        std::cout << "| ";
        for (int c = 0; c < N; ++c) {
            if (c % 3 == 0 && c != 0) {
                std::cout << "| ";
            }
            if (grid_[r][c] == 0) {
                std::cout << ". ";
            } else {
                std::cout << grid_[r][c] << " ";
            }
        }
        std::cout << "|\n";
    }
    std::cout << "+-------+-------+-------+\n";
}

void Sudoku::printSolution(const std::string& title) const {
    std::cout << "\n=== " << title << " ===\n";
    std::cout << "+-------+-------+-------+\n";
    for (int r = 0; r < N; ++r) {
        if (r % 3 == 0 && r != 0) {
            std::cout << "+-------+-------+-------+\n";
        }
        std::cout << "| ";
        for (int c = 0; c < N; ++c) {
            if (c % 3 == 0 && c != 0) {
                std::cout << "| ";
            }
            if (solution_[r][c] == 0) {
                std::cout << ". ";
            } else {
                std::cout << solution_[r][c] << " ";
            }
        }
        std::cout << "|\n";
    }
    std::cout << "+-------+-------+-------+\n";
}

Sudoku::Grid Sudoku::createExamplePuzzle() {
    Grid puzzle = {{
        {5, 3, 0, 0, 7, 0, 0, 0, 0},
        {6, 0, 0, 1, 9, 5, 0, 0, 0},
        {0, 9, 8, 0, 0, 0, 0, 6, 0},
        {8, 0, 0, 0, 6, 0, 0, 0, 3},
        {4, 0, 0, 8, 0, 3, 0, 0, 1},
        {7, 0, 0, 0, 2, 0, 0, 0, 6},
        {0, 6, 0, 0, 0, 0, 2, 8, 0},
        {0, 0, 0, 4, 1, 9, 0, 0, 5},
        {0, 0, 0, 0, 8, 0, 0, 7, 9}
    }};
    return puzzle;
}

bool Sudoku::isValid(int row, int col, int num) const {
    for (int x = 0; x < N; ++x) {
        if (solution_[row][x] == num) return false;
        if (solution_[x][col] == num) return false;
    }
    int startRow = row - row % 3;
    int startCol = col - col % 3;
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            if (solution_[startRow + i][startCol + j] == num) return false;
        }
    }
    return true;
}

bool Sudoku::findEmpty(int& row, int& col) const {
    for (row = 0; row < N; ++row) {
        for (col = 0; col < N; ++col) {
            if (solution_[row][col] == 0) return true;
        }
    }
    return false;
}

bool Sudoku::solveRecursive(Grid& grid) {
    int row, col;
    if (!findEmpty(row, col)) return true;

    for (int num = 1; num <= 9; ++num) {
        if (isValid(row, col, num)) {
            grid[row][col] = num;
            solution_[row][col] = num;
            if (solveRecursive(grid)) return true;
            grid[row][col] = 0;
            solution_[row][col] = 0;
        }
    }
    return false;
}

