#include "Sudoku.hpp"
#include <iostream>

Sudoku::Sudoku()
        : _grid{}, _solution{}, _solved(false)
{
	_grid.fill({});
	_solution.fill({});
}

Sudoku::Sudoku(const Grid& initialGrid)
        : _grid(initialGrid), _solution(initialGrid), _solved(false)
{

}

void Sudoku::setGrid(const Grid& grid)
{
	_grid = grid;
	_solution = grid;
	_solved = false;
}

Sudoku::Grid Sudoku::getGrid() const
{
	return _grid;
}

Sudoku::Grid Sudoku::getSolution() const
{
	return _solution;
}

bool Sudoku::solve()
{
	_solution = _grid;
	_solved = solveRecursive(_solution);

	return _solved;
}

bool Sudoku::isSolved() const
{
	return _solved;
}

void Sudoku::Draw(bool draw_start) const
{
	const Grid& grid = draw_start ? _grid : _solution;

	std::cout << "+-------+-------+-------+\n";

	for (int r = 0; r < N; ++r)
	{
		if (r % 3 == 0 && r != 0)
		{
			std::cout << "+-------+-------+-------+\n";
		}

		std::cout << "| ";

		for (int c = 0; c < N; ++c)
		{
			if (c % 3 == 0 && c != 0)
			{
				std::cout << "| ";
			}

			if (grid[r][c] == 0)
			{
				std::cout << ". ";
			}
			else
			{
				std::cout << grid[r][c] << " ";
			}
		}

		std::cout << "|\n";
	}
	std::cout << "+-------+-------+-------+\n";
}

bool Sudoku::isValid(int row, int col, int num) const
{
	for (int x = 0; x < N; ++x)
	{
		if (_solution[row][x] == num)
			return false;

		if (_solution[x][col] == num)
			return false;
	}

	int startRow = row - row % 3;
	int startCol = col - col % 3;

	for (int i = 0; i < 3; ++i)
		for (int j = 0; j < 3; ++j)
			if (_solution[startRow + i][startCol + j] == num)
				return false;

	return true;
}

bool Sudoku::findEmpty(int& row, int& col) const
{
	for (row = 0; row < N; ++row)
		for (col = 0; col < N; ++col)
			if (_solution[row][col] == 0)
				return true;

	return false;
}

bool Sudoku::solveRecursive(Grid& grid)
{
	int row, col;

	if (!findEmpty(row, col))
		return true;

	for (int num = 1; num <= 9; ++num)
	{
		if (isValid(row, col, num))
		{
			grid[row][col] = num;
			_solution[row][col] = num;

			if (solveRecursive(grid))
				return true;

			grid[row][col] = 0;
			_solution[row][col] = 0;
		}
	}

	return false;
}

