#include <Sudoku.hpp>
#include <iostream>
#include <algorithm>

using Mask = Sudoku::Mask;

Sudoku::Sudoku()
	: _grid{}, _solution{}, _solved(false)
{
	_grid.fill({});
	_solution.fill({});
	std::fill(std::begin(_cell_candidates), std::end(_cell_candidates), 0);
}

Sudoku::Sudoku(const Grid& initialGrid)
	: _grid(initialGrid), _solution(initialGrid), _solved(false)
{
	std::fill(std::begin(_cell_candidates), std::end(_cell_candidates), 0);
}

void Sudoku::setGrid(const Grid& grid)
{
	_grid = grid;
	_solution = grid;
	_solved = false;
	std::fill(std::begin(_rows), std::end(_rows), 0);
	std::fill(std::begin(_cols), std::end(_cols), 0);
	std::fill(std::begin(_boxes), std::end(_boxes), 0);
	std::fill(std::begin(_cell_candidates), std::end(_cell_candidates), 0);
}

bool Sudoku::solve()
{
	_solution = _grid;
	std::fill(std::begin(_rows), std::end(_rows), 0);
	std::fill(std::begin(_cols), std::end(_cols), 0);
	std::fill(std::begin(_boxes), std::end(_boxes), 0);

	// Initialize masks from givens
	for (int r = 0; r < N; ++r) {
		for (int c = 0; c < N; ++c) {
			int num = _solution[r][c];
			if (num != 0) {
				Mask m = DIGIT_MASK[num];
				_rows[r] |= m;
				_cols[c] |= m;
				_boxes[BOX_OF[r * 9 + c]] |= m;
			}
		}
	}

	// Initialize cell candidates
	for (int r = 0; r < N; ++r) {
		for (int c = 0; c < N; ++c) {
			if (_solution[r][c] == 0) {
				_cell_candidates[r * 9 + c] = _getCandidates(r, c);
			} else {
				_cell_candidates[r * 9 + c] = 0;
			}
		}
	}

	// Apply constraint propagation before search
	_propagate();

	_solved = _solveRecursive();
	return _solved;
}

void Sudoku::Draw(bool draw_start) const
{
	const Grid& grid = draw_start ? _grid : _solution;

	std::cout << "+-------+-------+-------+\n";

	for (int r = 0; r < N; ++r)
	{
		if (r % 3 == 0 && r != 0)
		{
			std::cout << "+-------+-------+-------+\n";
		}

		std::cout << "| ";

		for (int c = 0; c < N; ++c)
		{
			if (c % 3 == 0 && c != 0)
			{
				std::cout << "| ";
			}

			if (grid[r][c] == 0)
			{
				std::cout << ". ";
			}
			else
			{
				std::cout << grid[r][c] << " ";
			}
		}

		std::cout << "|\n";
	}
	std::cout << "+-------+-------+-------+\n";
}

bool Sudoku::_isValid(int row, int col, int num) const
{
	Mask m = DIGIT_MASK[num];
	int b = BOX_OF[row * 9 + col];
	return !(_rows[row] & m) && !(_cols[col] & m) && !(_boxes[b] & m);
}

Mask Sudoku::_getCandidates(int row, int col) const
{
	int b = BOX_OF[row * 9 + col];
	return ~(_rows[row] | _cols[col] | _boxes[b]) & 0x3FE; // bits 1-9
}

void Sudoku::_updateCandidates(int row, int col)
{
	if (_solution[row][col] == 0) {
		_cell_candidates[row * 9 + col] = _getCandidates(row, col);
	} else {
		_cell_candidates[row * 9 + col] = 0;
	}
}

int Sudoku::_countBits(Mask m) const
{
	return __builtin_popcount(m);
}

int Sudoku::_findBestCell() const
{
	int bestCell = -1;
	int minCandidates = 10;

	for (int r = 0; r < N; ++r) {
		for (int c = 0; c < N; ++c) {
			if (_solution[r][c] == 0) {
				Mask candidates = _cell_candidates[r * 9 + c];
				int count = _countBits(candidates);
				if (count < minCandidates) {
					minCandidates = count;
					bestCell = r * 9 + c;
					if (count <= 1) return bestCell; // early exit
				}
			}
		}
	}
	return bestCell;
}

// Constraint propagation techniques
bool Sudoku::_propagate()
{
	bool progress = true;
	while (progress) {
		progress = false;
		progress |= _nakedSingles();
		progress |= _hiddenSingles();
		progress |= _nakedPairs();
		progress |= _lockedCandidates();
	}
	return true;
}

// Naked singles: cell with only 1 candidate
bool Sudoku::_nakedSingles()
{
	bool progress = false;
	for (int r = 0; r < N; ++r) {
		for (int c = 0; c < N; ++c) {
			if (_solution[r][c] == 0) {
				Mask candidates = _cell_candidates[r * 9 + c];
				if (candidates && (candidates & (candidates - 1)) == 0) {
					// Only one bit set
					int num = __builtin_ctz(candidates);
					_solution[r][c] = num;
					Mask m = DIGIT_MASK[num];
					_rows[r] |= m;
					_cols[c] |= m;
					_boxes[BOX_OF[r * 9 + c]] |= m;
					_cell_candidates[r * 9 + c] = 0;
					progress = true;
				}
			}
		}
	}
	if (progress) {
		// Update all affected cells
		for (int r = 0; r < N; ++r) {
			for (int c = 0; c < N; ++c) {
				_updateCandidates(r, c);
			}
		}
	}
	return progress;
}

// Hidden singles: digit appears only once in a house
bool Sudoku::_hiddenSingles()
{
	bool progress = false;

	// Check rows
	for (int r = 0; r < N; ++r) {
		for (int d = 1; d <= 9; ++d) {
			Mask m = DIGIT_MASK[d];
			if (_rows[r] & m) continue; // already placed
			int count = 0, last_c = -1;
			for (int c = 0; c < N; ++c) {
				if (_solution[r][c] == 0 && (_cell_candidates[r * 9 + c] & m)) {
					count++;
					last_c = c;
				}
			}
			if (count == 1) {
				_solution[r][last_c] = d;
				_rows[r] |= m;
				_cols[last_c] |= m;
				_boxes[BOX_OF[r * 9 + last_c]] |= m;
				_cell_candidates[r * 9 + last_c] = 0;
				progress = true;
			}
		}
	}

	// Check columns
	for (int c = 0; c < N; ++c) {
		for (int d = 1; d <= 9; ++d) {
			Mask m = DIGIT_MASK[d];
			if (_cols[c] & m) continue;
			int count = 0, last_r = -1;
			for (int r = 0; r < N; ++r) {
				if (_solution[r][c] == 0 && (_cell_candidates[r * 9 + c] & m)) {
					count++;
					last_r = r;
				}
			}
			if (count == 1) {
				_solution[last_r][c] = d;
				_rows[last_r] |= m;
				_cols[c] |= m;
				_boxes[BOX_OF[last_r * 9 + c]] |= m;
				_cell_candidates[last_r * 9 + c] = 0;
				progress = true;
			}
		}
	}

	// Check boxes
	for (int b = 0; b < 9; ++b) {
		for (int d = 1; d <= 9; ++d) {
			Mask m = DIGIT_MASK[d];
			if (_boxes[b] & m) continue;
			int count = 0, last_cell = -1;
			for (int i = 0; i < 81; ++i) {
				int r = i / 9, c = i % 9;
				if (BOX_OF[i] == b && _solution[r][c] == 0 && (_cell_candidates[i] & m)) {
					count++;
					last_cell = i;
				}
			}
			if (count == 1) {
				int r = last_cell / 9, c = last_cell % 9;
				_solution[r][c] = d;
				_rows[r] |= m;
				_cols[c] |= m;
				_boxes[b] |= m;
				_cell_candidates[last_cell] = 0;
				progress = true;
			}
		}
	}

	if (progress) {
		for (int r = 0; r < N; ++r) {
			for (int c = 0; c < N; ++c) {
				_updateCandidates(r, c);
			}
		}
	}
	return progress;
}

// Naked pairs: two cells in a house with same 2 candidates
bool Sudoku::_nakedPairs()
{
	bool progress = false;

	auto processHouse = [&](auto getCells) -> bool {
		bool local_progress = false;
		for (int d = 1; d <= 9; ++d) {
			Mask pair_mask = DIGIT_MASK[d];
			// Find cells with exactly 2 candidates
			// This is simplified - full implementation would check all pairs
		}
		return local_progress;
	};

	// Simplified: skip for now, but structure is ready
	// Full naked pairs/triples implementation would go here
	return progress;
}

// Locked candidates (pointing pairs, box-line reduction)
bool Sudoku::_lockedCandidates()
{
	bool progress = false;

	// Box-line reduction: if a digit in a box is confined to one row/col,
	// eliminate it from rest of that row/col outside the box
	for (int b = 0; b < 9; ++b) {
		for (int d = 1; d <= 9; ++d) {
			Mask m = DIGIT_MASK[d];
			if (_boxes[b] & m) continue;

			// Find all cells in box with this candidate
			int rows_mask = 0, cols_mask = 0;
			int count = 0;
			for (int i = 0; i < 81; ++i) {
				if (BOX_OF[i] == b && _cell_candidates[i] & m) {
					int r = i / 9, c = i % 9;
					rows_mask |= 1 << r;
					cols_mask |= 1 << c;
					count++;
				}
			}

			// If all in same row, eliminate from rest of row
			if (count > 1 && (rows_mask & (rows_mask - 1)) == 0) {
				int r = __builtin_ctz(rows_mask);
				for (int c = 0; c < N; ++c) {
					if (BOX_OF[r * 9 + c] != b && _solution[r][c] == 0 && (_cell_candidates[r * 9 + c] & m)) {
						_cell_candidates[r * 9 + c] &= ~m;
						progress = true;
					}
				}
			}

			// If all in same col, eliminate from rest of col
			if (count > 1 && (cols_mask & (cols_mask - 1)) == 0) {
