	{
		auto start = Clock::now();
		for (int i = 0; i < 100; ++i) {
			SudokuDLX::solve(hard_puzzle, sol);
		}
		auto end = Clock::now();
		auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);
		std::cout << "DLX (Algorithm X): "
			<< duration.count() / 100.0 << " µs avg\n";
	}

	// Test bit-packed grid
