#ifndef SUDOKU_H
#define SUDOKU_H

#include <array>
#include <cstdint>
#include <string>

class Sudoku
{
public:
	// 1. Forward type declarations
	using Grid = std::array<std::array<int, 9>, 9>;
	static constexpr int N = 9;
	using Mask = uint16_t;  // bits 1-9 = candidates

	// Bit-packed grid: 81 cells × 4 bits = 324 bits = 6 × uint64_t (384 bits)
	using PackedGrid = std::array<uint64_t, 6>;

	// 2. Static data members
	static constexpr Grid EXAMPLE_PUZZLE = {{
		{5, 3, 0, 0, 7, 0, 0, 0, 0},
		{6, 0, 0, 1, 9, 5, 0, 0, 0},
		{0, 9, 8, 0, 0, 0, 0, 6, 0},

		{8, 0, 0, 0, 6, 0, 0, 0, 3},
		{4, 0, 0, 8, 0, 3, 0, 0, 1},
		{7, 0, 0, 0, 2, 0, 0, 0, 6},

		{0, 6, 0, 0, 0, 0, 2, 8, 0},
		{0, 0, 0, 4, 1, 9, 0, 0, 5},
		{0, 0, 0, 0, 8, 0, 0, 7, 9}
	}};

private:
	// Member variables (early visibility of state)
	Grid _grid;
	Grid _solution;
	bool _solved;

	// Bitmask state for O(1) constraint checking
	Mask _rows[9] = {};
	Mask _cols[9] = {};
	Mask _boxes[9] = {};

	// Precomputed lookup tables
	static constexpr Mask DIGIT_MASK[10] = {
		0,          // 0 (unused)
		1 << 1,     // 1
		1 << 2,     // 2
		1 << 3,     // 3
		1 << 4,     // 4
		1 << 5,     // 5
		1 << 6,     // 6
		1 << 7,     // 7
		1 << 8,     // 8
		1 << 9      // 9
	};

	static constexpr int BOX_OF[81] = {
		0,0,0, 1,1,1, 2,2,2,
		0,0,0, 1,1,1, 2,2,2,
		0,0,0, 1,1,1, 2,2,2,

		3,3,3, 4,4,4, 5,5,5,
		3,3,3, 4,4,4, 5,5,5,
		3,3,3, 4,4,4, 5,5,5,

		6,6,6, 7,7,7, 8,8,8,
		6,6,6, 7,7,7, 8,8,8,
		6,6,6, 7,7,7, 8,8,8
	};

	// Bit-packed candidates for each cell (4 bits per cell = 81 × 4 = 324 bits)
	// Stored as 6 × uint64_t = 384 bits
	Mask _cell_candidates[81];

public:
	// 3. Constructors
	Sudoku();
	explicit Sudoku(const Grid& initialGrid);

