		0, 0, 0, 4, 1, 9, 0, 0, 5,
		0, 0, 0, 0, 8, 0, 0, 7, 9
	};

private:
	// Member variables (early visibility of state)
	Grid _grid;
	Grid _solution;
	bool _solved;

