		1 << 4,     // 4
		1 << 5,     // 5
		1 << 6,     // 6
		1 << 7,     // 7
		1 << 8,     // 8
		1 << 9      // 9
	};

	static constexpr int BOX_OF[81] = {
		0,0,0, 1,1,1, 2,2,2,
		0,0,0, 1,1,1, 2,2,2,
		0,0,0, 1,1,1, 2,2,2,

