				int i = idx(last_r, c);
				_solution[i] = d;
				_rows[last_r] |= m;
				_cols[c] |= m;
				_boxes[BOX_OF[i]] |= m;
				_cell_candidates[i] = 0;
				progress = true;
			}
		}
	}

	// Check boxes
