				int r = i / 9, c = i % 9;
				_solution[i] = num;
				Mask m = DIGIT_MASK[num];
				_rows[r] |= m;
				_cols[c] |= m;
				_boxes[BOX_OF[i]] |= m;
				_cell_candidates[i] = 0;
				progress = true;
			}
		}
	}
	if (progress) {
		for (int r = 0; r < N; ++r) {
			for (int c = 0; c < N; ++c) {
				_updateCandidates(r, c);
			}
		}
	}
	return progress;
}

// Hidden singles: digit appears only once in a house
bool Sudoku::_hiddenSingles()
{
	bool progress = false;

	// Check rows
	for (int r = 0; r < N; ++r) {
		for (int d = 1; d <= 9; ++d) {
			Mask m = DIGIT_MASK[d];
			if (_rows[r] & m) continue;
			int count = 0, last_c = -1;
			for (int c = 0; c < N; ++c) {
				int i = idx(r, c);
				if (_solution[i] == 0 && (_cell_candidates[i] & m)) {
					count++;
					last_c = c;
				}
			}
			if (count == 1) {
				int i = idx(r, last_c);
				_solution[i] = d;
				_rows[r] |= m;
				_cols[last_c] |= m;
				_boxes[BOX_OF[i]] |= m;
				_cell_candidates[i] = 0;
				progress = true;
			}
		}
	}

	// Check columns
	for (int c = 0; c < N; ++c) {
		for (int d = 1; d <= 9; ++d) {
			Mask m = DIGIT_MASK[d];
			if (_cols[c] & m) continue;
			int count = 0, last_r = -1;
			for (int r = 0; r < N; ++r) {
				int i = idx(r, c);
				if (_solution[i] == 0 && (_cell_candidates[i] & m)) {
					count++;
					last_r = r;
				}
			}
			if (count == 1) {
				int i = idx(last_r, c);
				_solution[i] = d;
				_rows[last_r] |= m;
				_cols[c] |= m;
				_boxes[BOX_OF[i]] |= m;
				_cell_candidates[i] = 0;
				progress = true;
			}
		}
	}

	// Check boxes
	for (int b = 0; b < 9; ++b) {
		for (int d = 1; d <= 9; ++d) {
			Mask m = DIGIT_MASK[d];
			if (_boxes[b] & m) continue;
			int count = 0, last_cell = -1;
			for (int i = 0; i < 81; ++i) {
				if (BOX_OF[i] == b && _solution[i] == 0 && (_cell_candidates[i] & m)) {
					count++;
					last_cell = i;
				}
			}
			if (count == 1) {
				int r = last_cell / 9, c = last_cell % 9;
				_solution[last_cell] = d;
				_rows[r] |= m;
				_cols[c] |= m;
				_boxes[b] |= m;
				_cell_candidates[last_cell] = 0;
				progress = true;
			}
		}
	}

	if (progress) {
		for (int r = 0; r < N; ++r) {
			for (int c = 0; c < N; ++c) {
				_updateCandidates(r, c);
			}
		}
	}
	return progress;
}

bool Sudoku::_solveRecursive()
{
	int cell = _findBestCell();
	if (cell == -1) return true; // solved

	int row = cell / 9;
	int col = cell % 9;
	Mask candidates = _cell_candidates[cell];
	int b = BOX_OF[cell];

	// Try each candidate
	while (candidates) {
		Mask m = candidates & -candidates;
		int num = __builtin_ctz(m);
		candidates &= candidates - 1;

		// Place digit
		_solution[cell] = num;
		_rows[row] |= m;
		_cols[col] |= m;
		_boxes[b] |= m;

		// Save and update affected candidates
		Mask saved[81];
		for (int i = 0; i < 81; ++i) saved[i] = _cell_candidates[i];

		for (int r = 0; r < N; ++r) {
			for (int c = 0; c < N; ++c) {
				int i = idx(r, c);
				if (_solution[i] == 0 && (_cell_candidates[i] & m)) {
					_cell_candidates[i] &= ~m;
				}
			}
		}

		if (_solveRecursive())
			return true;

		// Backtrack
		_solution[cell] = 0;
		_rows[row] &= ~m;
		_cols[col] &= ~m;
		_boxes[b] &= ~m;

		// Restore candidates
		for (int i = 0; i < 81; ++i) _cell_candidates[i] = saved[i];
	}

	return false;
}

// Bit-packed grid utilities
Sudoku::PackedGrid Sudoku::packGrid(const Grid& grid)
{
	PackedGrid packed = {};
	for (int i = 0; i < 81; ++i) {
		int bit_pos = i * 4;
		int word = bit_pos / 64;
		int shift = bit_pos % 64;
		packed[word] |= (static_cast<uint64_t>(grid[i]) << shift);
	}
	return packed;
}

Sudoku::Grid Sudoku::unpackGrid(const PackedGrid& packed)
{
	Grid grid = {};
	for (int i = 0; i < 81; ++i) {
		int bit_pos = i * 4;
		int word = bit_pos / 64;
		int shift = bit_pos % 64;
		grid[i] = static_cast<uint16_t>((packed[word] >> shift) & 0xF);
	}
	return grid;
}

#ifndef SUDOKU_DLX_H
#define SUDOKU_DLX_H

#include <array>
#include <cstdint>
#include <vector>

class SudokuDLX
{
public:
	using Grid = std::array<uint16_t, 81>;

	// Solve puzzle using Algorithm X with Dancing Links
	// Returns true if solved, false if no solution
	static bool solve(const Grid& puzzle, Grid& solution);

	// Validate a completed grid
	static bool validate(const Grid& grid);

private:
	// DLX node structure
	struct Node {
		Node* left = nullptr;
		Node* right = nullptr;
		Node* up = nullptr;
		Node* down = nullptr;
		Node* column = nullptr;
		int row_id = -1;      // which puzzle row (0-728)
		int constraint_id = -1; // which constraint column (0-323)
		int size = 0;         // column size (only valid for column headers)
	};

	// 4 constraint types × 81 = 324 columns
	// Row constraint: cell (r,c) has a digit
	// Col constraint: row r has digit d
	// Box constraint: col c has digit d
	// Box constraint: box b has digit d
	static constexpr int COLS = 324;
	static constexpr int ROWS = 729; // 9×9×9 = 729 possible placements

	// Build the DLX matrix for a given puzzle
	static void buildMatrix(const Grid& puzzle, std::vector<Node>& nodes, Node* headers[COLS]);

	// Cover/uncover column
	static void cover(Node* c);
	static void uncover(Node* c);

	// Search with heuristic (choose column with minimum size)
	static bool search(Node* headers[COLS], std::vector<int>& solution_rows, int depth = 0);

	// Decode solution rows back to grid
	static void decodeSolution(const std::vector<int>& solution_rows, Grid& solution);

	// Constraint column index calculations
	static constexpr int idx(int r, int c) { return r * 9 + c; }
	static constexpr int cellCol(int r, int c) { return idx(r, c); }                    // 0-80
	static constexpr int rowCol(int r, int d) { return 81 + r * 9 + (d - 1); }         // 81-161
	static constexpr int colCol(int c, int d) { return 162 + c * 9 + (d - 1); }        // 162-242
	static constexpr int boxCol(int b, int d) { return 243 + b * 9 + (d - 1); }        // 243-323
	static constexpr int boxOf(int r, int c) { return (r / 3) * 3 + (c / 3); }
};

#endif // SUDOKU_DLX_H

