	for (int r = 0; r < N; ++r)
	{
		if (r % 3 == 0 && r != 0)
		{
			std::cout << "+-------+-------+-------+\n";
		}

		std::cout << "| ";

		for (int c = 0; c < N; ++c)
		{
			if (c % 3 == 0 && c != 0)
			{
				std::cout << "| ";
			}

			int val = grid[idx(r, c)];
			if (val == 0)
			{
				std::cout << ". ";
			}
			else
			{
				std::cout << val << " ";
			}
		}

		std::cout << "|\n";
