222	bool SudokuDLX::validate(const Grid& grid)
223	{
224		// Check rows
225		for (int r = 0; r < 9; ++r)
226		{
227			uint16_t seen = 0;
228	
229			for (int c = 0; c < 9; ++c)
230			{
231				int v = grid[idx(r, c)];
232	
233				if (v < 1 || v > 9)
234					return false;
235				
236				if (seen & (1 << v))
237					return false;
238				
239				seen |= 1 << v;
240			}
241		}
242	
243		// Check columns
244		for (int c = 0; c < 9; ++c)
245		{
246			uint16_t seen = 0;
247	
248			for (int r = 0; r < 9; ++r)
249			{
250				int v = grid[idx(r, c)];
251	
252				if (seen & (1 << v))
253					return false;
254				
255				seen |= 1 << v;
256			}
257		}
258	
259		// Check boxes
260		for (int br = 0; br < 3; ++br)
261		{
262			for (int bc = 0; bc < 3; ++bc)
263			{
264				uint16_t seen = 0;
265	
266				for (int r = 0; r < 3; ++r)
267				{
268					for (int c = 0; c < 3; ++c)
269					{
270						int v = grid[idx(br * 3 + r, bc * 3 + c)];
271	
272						if (seen & (1 << v))
273							return false;
274	
275						seen |= 1 << v;
276					}
277				}
278			}
279		}
280	
281		return true;
282	}
