17		std::cout << name << ": ";
18		if (solved)
19		{
20			std::cout << "SOLVED in " << duration.count() << " µs\n";
21		}
22		else
23		{
24			std::cout << "FAILED\n";
25		}
26	}
27	
28	int main()
