			std::cout << "Solutions: MISMATCH!\n";
			s1.Draw(false);
			SudokuDLX::Draw(sol2, false);
		}
	} else if (!solved1 && !solved2) {
		std::cout << "Both failed (unsolvable?)\n";
	} else {
		std::cout << "MISMATCH: Bitmask=" << (solved1 ? "solved" : "failed")
			<< " DLX=" << (solved2 ? "solved" : "failed") << "\n";
	}
}

