	for (int i = 0; i < 3; ++i) {
		Sudoku s(Sudoku::HARD_PUZZLE);
		s.solve();
		SudokuDLX::solve(Sudoku::HARD_PUZZLE, hard_solution);
	}

	// Benchmark bitmask solver on hard puzzle
	{
		auto start = Clock::now();
