305	int Sudoku::_findBestCell() const
306	{
307	#if SUDOKU_AVX2
308		// Vectorized: find cell with minimum candidates among empty cells
309		// We need to consider only cells where _solution[i] == 0
310		// Create a mask of valid (empty) cells
311		int min_count = 10;
312		int best_idx = -1;
313	
314		// Process 16 cells at a time
315		for (int base = 0; base < 81; base += 16) {
316			int remaining = 81 - base;
317			int process = (remaining >= 16) ? 16 : remaining;
318	
319			// Load candidates for this chunk
320			alignas(32) Mask chunk_candidates[16];
321			alignas(32) uint16_t chunk_solution[16];
322	
323			for (int j = 0; j < process; ++j) {
324				chunk_candidates[j] = _cell_candidates[base + j];
325				chunk_solution[j] = _solution[base + j];
326			}
327			// Zero-pad the rest
328			for (int j = process; j < 16; ++j) {
329				chunk_candidates[j] = 0;
330				chunk_solution[j] = 1; // non-zero = filled
331			}
332	
333			__m256i vec_cand = SudokuAVX2::load_candidates(chunk_candidates);
334			__m256i vec_sol = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(chunk_solution));
