// Precomputed peers for each cell (20 peers: same row, col, box excluding self)
constexpr int Sudoku::PEERS[81][20] = []() {
    int peers[81][20] = {};
    for (int i = 0; i < 81; ++i) {
        int r = i / 9, c = i % 9, b = Sudoku::BOX_OF[i];
        int p = 0;
        // Row peers
        for (int cc = 0; cc < 9; ++cc) if (cc != c) peers[i][p++] = Sudoku::idx(r, cc);
        // Col peers
        for (int rr = 0; rr < 9; ++rr) if (rr != r) peers[i][p++] = Sudoku::idx(rr, c);
        // Box peers
        int br = (r / 3) * 3, bc = (c / 3) * 3;
        for (int dr = 0; dr < 3; ++dr) {
            for (int dc = 0; dc < 3; ++dc) {
                int rr = br + dr, cc = bc + dc;
                if (rr != r || cc != c) peers[i][p++] = Sudoku::idx(rr, cc);
            }
        }
    }
    return peers;
}();

