2	# Two-phase PGO build script for Clang/GCC
3	# Usage: ./scripts/pgo_build.sh [clang|gcc]
4	
5	set -euo pipefail
6	
7	COMPILER="${1:-clang}"
8	BUILD_DIR_GEN="build_pgo_gen"
9	BUILD_DIR_USE="build_pgo_use"
10	PROFILE_DIR="pgo_profiles"
11	MERGED_PROFILE="${PROFILE_DIR}/merged.profdata"
12	
13	echo "=== PGO Two-Phase Build for ${COMPILER} ==="
14	
15	# Phase 1: Build with profile generation
16	echo "Phase 1: Building with -fprofile-generate in ${BUILD_DIR_GEN}..."
17	cmake -B "${BUILD_DIR_GEN}" -S . \
18	    -DCMAKE_CXX_COMPILER="${COMPILER}++" \
19	    -DCMAKE_BUILD_TYPE=Release \
20	    -DENABLE_PGO=ON \
21	    -DENABLE_LTO=ON
22	
23	cmake --build "${BUILD_DIR_GEN}" --config Release -j$(nproc)
24	
25	# Run representative workload to generate profiles
26	echo "Phase 1b: Running benchmarks to generate profile data..."
27	mkdir -p "${PROFILE_DIR}"
28	# LLVM_PROFILE_FILE specifies where to write .profraw files
29	LLVM_PROFILE_FILE="${PROFILE_DIR}/profile-%p.profraw" \
30	    "${BUILD_DIR_GEN}/hello" 2>&1 | tail -20
31	
32	# Merge profiles
33	echo "Phase 1c: Merging profiles..."
34	if command -v llvm-profdata >/dev/null 2>&1; then
35	    llvm-profdata merge -o "${MERGED_PROFILE}" "${PROFILE_DIR}"/profile-*.profraw
36	elif command -v gcc-profdata >/dev/null 2>&1; then
37	    # GCC doesn't have standard profdata tool; use gcov-tool
38	    echo "GCC: using gcov-tool (if available)"
39	    # gcov-tool merge ... (complex, skipping for now)
40	else
41	    echo "Warning: No profdata merge tool found. Install llvm-profdata or use GCC's gcov."
42	    exit 1
43	fi
44	
45	echo "Merged profile: ${MERGED_PROFILE}"
46	
47	# Phase 2: Build with profile use
48	echo "Phase 2: Building with -fprofile-use in ${BUILD_DIR_USE}..."
49	PGO_USE_PROFILE="${MERGED_PROFILE}" \
50	cmake -B "${BUILD_DIR_USE}" -S . \
51	    -DCMAKE_CXX_COMPILER="${COMPILER}++" \
