525	// Hidden singles: digit appears only once in a house
526	bool Sudoku::_hiddenSingles()
527	{
528		bool progress = false;
529	
530		// Check rows
531		for (int r = 0; r < N; ++r) {
532			for (int d = 1; d <= 9; ++d) {
533				Mask m = DIGIT_MASK[d];
534				if (_rows[r] & m) continue;
535				int count = 0, last_c = -1;
536				for (int c = 0; c < N; ++c) {
537					int i = idx(r, c);
538					if (_solution[i] == 0 && (_cell_candidates[i] & m)) {
539						count++;
540						last_c = c;
541					}
542				}
543				if (count == 1) {
544					int i = idx(r, last_c);
545					_solution[i] = d;
546					_rows[r] |= m;
547					_cols[last_c] |= m;
548					_boxes[BOX_OF[i]] |= m;
549					_cell_candidates[i] = 0;
550					progress = true;
551				}
552			}
553		}
554	
555		// Check columns
556		for (int c = 0; c < N; ++c) {
557			for (int d = 1; d <= 9; ++d) {
558				Mask m = DIGIT_MASK[d];
559				if (_cols[c] & m) continue;
560				int count = 0, last_r = -1;
561				for (int r = 0; r < N; ++r) {
562					int i = idx(r, c);
563					if (_solution[i] == 0 && (_cell_candidates[i] & m)) {
564						count++;
565						last_r = r;
566					}
567				}
568				if (count == 1) {
569					int i = idx(last_r, c);
570					_solution[i] = d;
571					_rows[last_r] |= m;
572					_cols[c] |= m;
573					_boxes[BOX_OF[i]] |= m;
574					_cell_candidates[i] = 0;
575					progress = true;
576				}
577			}
578		}
579	
580		// Check boxes
581		for (int b = 0; b < 9; ++b) {
582			for (int d = 1; d <= 9; ++d) {
583				Mask m = DIGIT_MASK[d];
584				if (_boxes[b] & m) continue;
585				int count = 0, last_cell = -1;
586				for (int i = 0; i < 81; ++i) {
587					if (BOX_OF[i] == b && _solution[i] == 0 && (_cell_candidates[i] & m)) {
588						count++;
589						last_cell = i;
590					}
591				}
592				if (count == 1) {
593					int r = last_cell / 9, c = last_cell % 9;
594					_solution[last_cell] = d;
595					_rows[r] |= m;
596					_cols[c] |= m;
597					_boxes[b] |= m;
598					_cell_candidates[last_cell] = 0;
599					progress = true;
600				}
601			}
602		}
603	
604		if (progress) {
605			for (int r = 0; r < N; ++r) {
606				for (int c = 0; c < N; ++c) {
607					_updateCandidates(r, c);
608				}
609			}
610		}
611		return progress;
612	}
