bool SudokuDLX::validate(const Grid& grid)
{
	// Check rows
	for (int r = 0; r < 9; ++r)
	{
		uint16_t seen = 0;

		for (int c = 0; c < 9; ++c)
		{
			int v = grid[idx(r, c)];

			if (v < 1 || v > 9)
				return false;

			if (seen & (1 << v))
				return false;

			seen |= 1 << v;
		}
	}

	// Check columns
	for (int c = 0; c < 9; ++c)
	{
		uint16_t seen = 0;

		for (int r = 0; r < 9; ++r)
		{
			int v = grid[idx(r, c)];

			if (seen & (1 << v))
				return false;

			seen |= 1 << v;
		}
	}

	// Check boxes
	for (int br = 0; br < 3; ++br)
	{
		for (int bc = 0; bc < 3; ++bc)
		{
			uint16_t seen = 0;

			for (int r = 0; r < 3; ++r)
			{
				for (int c = 0; c < 3; ++c)
				{
					int v = grid[idx(br * 3 + r, bc * 3 + c)];

					if (seen & (1 << v))
						return false;

					seen |= 1 << v;
				}
			}
		}
	}

	return true;
}

void SudokuDLX::Draw(const Grid& grid, bool draw_start)
{
	(void)draw_start; // unused for DLX, but kept for API compatibility

	std::cout << "+-------+-------+-------+\n";
	for (int r = 0; r < 9; ++r) {
		if (r % 3 == 0 && r != 0) {
			std::cout << "+-------+-------+-------+\n";
		}
		std::cout << "| ";
		for (int c = 0; c < 9; ++c) {
			if (c % 3 == 0 && c != 0) {
				std::cout << "| ";
			}
			int v = grid[idx(r, c)];
			if (v == 0) std::cout << ". ";
			else std::cout << v << ' ';
		}
		std::cout << "|\n";
	}
	std::cout << "+-------+-------+-------+\n";
}

