int main()
{
	std::cout << "Starting...\n" << std::flush;
	Grid puzzle = Sudoku::EXAMPLE_PUZZLE;
	Grid solution;

	std::cout << "=== Sudoku Solver Benchmark ===\n\n" << std::flush;

	// Draw starting puzzle
	std::cout << "Drawing puzzle...\n" << std::flush;
	SudokuDLX::Draw(puzzle, true);
