constexpr int Sudoku::PEERS[81][20] = []() {
    int peers[81][20] = {};
    for (int i = 0; i < 81; ++i) {
        int r = i / 9, c = i % 9, b = Sudoku::BOX_OF[i];
        int idx = 0;
        // Row peers
        for (int cc = 0; cc < 9; ++cc) if (cc != c) peers[i][idx++] = Sudoku::idx(r, cc);
        // Col peers
        for (int rr = 0; rr < 9; ++rr) if (rr != r) peers[i][idx++] = Sudoku::idx(rr, c);
