70	    // Vectorized popcount for 16 x 16-bit values using nibble lookup table
71	    // Returns popcount for each 16-bit lane in lower 8 bits of each 16-bit lane
72	    inline __m256i popcount_epi16(__m256i x)
73	    {
74	        // Split each 16-bit lane into 4 nibbles (4 bits each)
75	        // Use 16-entry lookup table (popcount for 0-15) duplicated across 256-bit lanes
76	        const __m256i popcnt_lut = _mm256_setr_epi8(
77	            0,1,1,2,1,2,2,3,1,2,2,3,2,3,3,4,  // lane 0: popcount for 0-15
78	            0,1,1,2,1,2,2,3,1,2,2,3,2,3,3,4   // lane 1: same (shuffle operates per 128-bit lane)
79	        );
80	
81	        // Extract low nibbles of each byte
82	        __m256i nibble_mask = _mm256_set1_epi8(0x0F);
83	        __m256i lo_nibble = _mm256_and_si256(x, nibble_mask);
84	        __m256i hi_nibble = _mm256_and_si256(_mm256_srli_epi16(x, 4), nibble_mask);
85	        __m256i lo2_nibble = _mm256_and_si256(_mm256_srli_epi16(x, 8), nibble_mask);
86	        __m256i hi2_nibble = _mm256_and_si256(_mm256_srli_epi16(x, 12), nibble_mask);
87	
88	        // Lookup popcount for each nibble
89	        __m256i cnt0 = _mm256_shuffle_epi8(popcnt_lut, lo_nibble);
90	        __m256i cnt1 = _mm256_shuffle_epi8(popcnt_lut, hi_nibble);
91	        __m256i cnt2 = _mm256_shuffle_epi8(popcnt_lut, lo2_nibble);
92	        __m256i cnt3 = _mm256_shuffle_epi8(popcnt_lut, hi2_nibble);
93	
94	        // Sum all 4 nibbles per 16-bit lane
95	        __m256i sum = _mm256_add_epi8(cnt0, cnt1);
96	        sum = _mm256_add_epi8(sum, cnt2);
97	        sum = _mm256_add_epi8(sum, cnt3);
98	
99	        // Mask to keep only low byte of each 16-bit lane (popcount fits in 4 bits max=9)
100	        return _mm256_and_si256(sum, _mm256_set1_epi16(0x00FF));
101	    }
