103	    // Check which lanes have exactly 1 candidate (naked singles)
104	    // Returns mask where each 16-bit lane is 0xFFFF if exactly 1 bit set, 0 otherwise
105	    inline __m256i naked_singles_mask(__m256i candidates)
106	    {
107	        // (candidates & (candidates - 1)) == 0 && candidates != 0
108	        __m256i dec = _mm256_sub_epi16(candidates, _mm256_set1_epi16(1));
109	        __m256i and_result = _mm256_and_si256(candidates, dec);
110	        __m256i is_zero = _mm256_cmpeq_epi16(and_result, _mm256_setzero_si256());
111	        __m256i non_zero = _mm256_cmpgt_epi16(candidates, _mm256_setzero_si256());
112	        return _mm256_and_si256(is_zero, non_zero);
113	    }
