125	    inline __m256i compute_candidates_row(__m256i row_mask, __m256i col_masks, __m256i box_masks)
126	    {
127	        __m256i combined = _mm256_or_si256(_mm256_or_si256(row_mask, col_masks), box_masks);
128	        __m256i all_digits = broadcast_mask(ALL_DIGITS);
129	        return _mm256_andnot_si256(combined, all_digits);
130	    }
