132	    // Find index of lane with minimum popcount (for MRV heuristic)
133	    // Returns -1 if all lanes are filled (candidates == 0)
134	    inline int find_min_candidates(const Mask* candidates, int count, int& min_count)
135	    {
136	        min_count = 10;
137	        int best_idx = -1;
138	
139	        // Process 16 at a time
140	        int i = 0;
141	        for (; i + LANES <= count; i += LANES) {
142	            __m256i vec = load_candidates(&candidates[i]);
143	            __m256i popcnts = popcount_epi16(vec);
144	
145	            // Extract popcounts and find minimum among non-zero candidates
146	            alignas(32) unsigned char counts[LANES];
147	            _mm256_storeu_si256(reinterpret_cast<__m256i*>(counts), popcnts);
148	
149	            for (int j = 0; j < LANES; ++j) {
150	                int c = counts[j];
151	                if (c > 0 && c < min_count) {
152	                    min_count = c;
153	                    best_idx = i + j;
154	                    if (c <= 1) return best_idx;
155	                }
156	            }
157	        }
158	
159	        // Scalar tail
160	        for (; i < count; ++i) {
161	            if (candidates[i] != 0) {
162	                int c = popcount(candidates[i]);
163	                if (c < min_count) {
164	                    min_count = c;
165	                    best_idx = i;
166	                    if (c <= 1) return best_idx;
167	                }
168	            }
169	        }
170	
171	        return best_idx;
