bool Sudoku::_solveRecursive()
{
	int cell = _findBestCell();
	if (cell == -1) {
		// No cell with candidates found - check if solved or contradiction
		for (int i = 0; i < 81; ++i) {
			if (_solution[i] == 0) return false; // empty cell with 0 candidates = contradiction
		}
		return true; // completely filled = solved
	}

	int row = cell / 9;
	int col = cell % 9;
	Mask candidates = _cell_candidates[cell];
	int b = BOX_OF[cell];

	// Try each candidate
	while (candidates) {
		Mask m = candidates & -candidates;
		int num = ctz(m);
		candidates &= candidates - 1;

		// Place digit
		_solution[cell] = num;
		_rows[row] |= m;
		_cols[col] |= m;
		_boxes[b] |= m;

		// Save full state before propagation (propagation can modify many cells)
		Mask saved_candidates[81];
		uint16_t saved_solution[81];
		Mask saved_rows[9], saved_cols[9], saved_boxes[9];

		for (int i = 0; i < 81; ++i) {
			saved_candidates[i] = _cell_candidates[i];
			saved_solution[i] = _solution[i];
		}
		for (int i = 0; i < 9; ++i) {
			saved_rows[i] = _rows[i];
			saved_cols[i] = _cols[i];
			saved_boxes[i] = _boxes[i];
		}

		// Update only peers of the placed cell
		for (int k = 0; k < 20; ++k) {
			int peer = PEERS[cell][k];
			if (_solution[peer] == 0) {
				_cell_candidates[peer] &= ~m;
			}
		}

		// Apply constraint propagation after placement
		if (_propagate()) {
			if (_solveRecursive())
				return true;
		}

		// Backtrack - restore full state
		for (int i = 0; i < 81; ++i) {
			_cell_candidates[i] = saved_candidates[i];
			_solution[i] = saved_solution[i];
		}
		for (int i = 0; i < 9; ++i) {
			_rows[i] = saved_rows[i];
			_cols[i] = saved_cols[i];
			_boxes[i] = saved_boxes[i];
		}
	}

	return false;
}

// Bit-packed grid utilities
Sudoku::PackedGrid Sudoku::packGrid(const Grid& grid)
{
	PackedGrid packed = {};
	for (int i = 0; i < 81; ++i) {
		int bit_pos = i * 4;
		int word = bit_pos / 64;
		int shift = bit_pos % 64;
		packed[word] |= (static_cast<uint64_t>(grid[i]) << shift);
	}
	return packed;
}

Sudoku::Grid Sudoku::unpackGrid(const PackedGrid& packed)
{
	Grid grid = {};
	for (int i = 0; i < 81; ++i) {
		int bit_pos = i * 4;
		int word = bit_pos / 64;
		int shift = bit_pos % 64;
		grid[i] = static_cast<uint16_t>((packed[word] >> shift) & 0xF);
	}
	return grid;
}

