176	Sudoku::Sudoku()
177		: _grid{}, _solution{}, _solved(false)
178	{
179		_grid.fill(0);
180		_solution.fill(0);
181		std::fill(std::begin(_cell_candidates), std::end(_cell_candidates), 0);
182	}
183	
184	Sudoku::Sudoku(const Grid& initialGrid)
185		: _grid(initialGrid), _solution(initialGrid), _solved(false)
186	{
187		std::fill(std::begin(_cell_candidates), std::end(_cell_candidates), 0);
188	}
189	
190	void Sudoku::setGrid(const Grid& grid)
191	{
192		_grid = grid;
193		_solution = grid;
194		_solved = false;
195		std::fill(std::begin(_rows), std::end(_rows), 0);
196		std::fill(std::begin(_cols), std::end(_cols), 0);
197		std::fill(std::begin(_boxes), std::end(_boxes), 0);
198		std::fill(std::begin(_cell_candidates), std::end(_cell_candidates), 0);
199	}
200	
201	bool Sudoku::solve()
202	{
203		_solution = _grid;
204		std::fill(std::begin(_rows), std::end(_rows), 0);
205		std::fill(std::begin(_cols), std::end(_cols), 0);
206		std::fill(std::begin(_boxes), std::end(_boxes), 0);
207	
208		// Initialize masks from givens with validation
209		for (int r = 0; r < N; ++r) {
210			for (int c = 0; c < N; ++c) {
211				int num = _solution[idx(r, c)];
212				if (num != 0) {
213					// Validate input range
214					if (num < 1 || num > 9) return false;
