                    Mask m = DIGIT_MASK[num];
                    if ((_rows[r] & m) || (_cols[c] & m) || (_boxes[BOX_OF[idx(r, c)]] & m))
                        return false;
                    _rows[r] |= m;
                    _cols[c] |= m;
                    _boxes[BOX_OF[idx(r, c)]] |= m;
                }
            }
        }

        // Initialize cell candidates
        for (int r = 0; r < N; ++r) {
            for (int c = 0; c < N; ++c) {
                int i = idx(r, c);
                if (_solution[i] == 0) {
                    _cell_candidates[i] = _getCandidates(r, c);
                } else {
                    _cell_candidates[i] = 0;
                }
            }
        }

        // Debug: print initial candidates
        std::cout << "Initial empty cells: ";
        int empty = 0;
        for (int i = 0; i < 81; ++i) if (_solution[i] == 0) empty++;
        std::cout << empty << "\n";

        std::cout << "Initial candidates for first 20 cells:\n";
        for (int i = 0; i < 20; ++i) {
            if (_solution[i] == 0) {
                int cnt = 0;
                for (int d = 1; d <= 9; ++d) if (_cell_candidates[i] & (1<<d)) cnt++;
                if (cnt > 0) std::cout << "  Cell " << i << ": " << cnt << " candidates\n";
            }
        }

        // Apply constraint propagation before search
        if (!_propagate())
            return false; // contradiction from givens

        _solved = _solveRecursive();
        return _solved;
    }

