#ifndef SUDOKU_DLX_H
#define SUDOKU_DLX_H

#include <array>
#include <cstdint>

class SudokuDLX
{
public:
	using Grid = std::array<uint16_t, 81>;

	// 4 constraint types × 81 = 324 columns
	// Row constraint: cell (r,c) has a digit
	// Col constraint: row r has digit d
	// Box constraint: col c has digit d
	// Box constraint: box b has digit d
	static constexpr int COLS = 324;
	static constexpr int ROWS = 729; // 9×9×9 = 729 possible placements

public:
	// DLX node structure
	struct Node {
		Node* left = nullptr;
		Node* right = nullptr;
		Node* up = nullptr;
		Node* down = nullptr;
		Node* column = nullptr;
		int row_id = -1;      // which puzzle row (0-728)
		int constraint_id = -1; // which constraint column (0-323)
		int size = 0;         // column size (only valid for column headers)
	};

	// Draw grid to stdout (same signature as Sudoku::Draw)
	static void Draw(const Grid& grid, bool draw_start = true);

	// Solve puzzle using Algorithm X with Dancing Links
	// Returns true if solved, false if no solution
	static bool solve(const Grid& puzzle, Grid& solution);

	// Validate a completed grid
	static bool validate(const Grid& grid);

private:
	// Build the DLX matrix for a given puzzle (uses fixed node buffer)
	static void buildMatrix(const Grid& puzzle, Node* headers[COLS]);

	// Cover/uncover column
	static void cover(Node* c);
	static void uncover(Node* c);

	// Search with heuristic (choose column with minimum size)
	// Uses fixed buffer for solution_rows (max 81)
	// root is the dummy root header (sentinel), not headers[0]
	static bool search(Node* root, int* solution_rows, int& solution_count, int depth = 0);

	// Decode solution rows back to grid
	static void decodeSolution(const int* solution_rows, int solution_count, Grid& solution);

	// Constraint column index calculations
	static constexpr int idx(int r, int c) { return r * 9 + c; }
	static constexpr int cellCol(int r, int c) { return idx(r, c); }                    // 0-80
	static constexpr int rowCol(int r, int d) { return 81 + r * 9 + (d - 1); }         // 81-161
	static constexpr int colCol(int c, int d) { return 162 + c * 9 + (d - 1); }        // 162-242
	static constexpr int boxCol(int b, int d) { return 243 + b * 9 + (d - 1); }        // 243-323
	static constexpr int boxOf(int r, int c) { return (r / 3) * 3 + (c / 3); }
};

#endif // SUDOKU_DLX_H

#include "SudokuDLX.hpp"
#include <algorithm>
#include <climits>
#include <iostream>

// Fixed buffer for nodes - avoids heap allocation
// Max nodes: 324 headers + 729 rows * 4 nodes = 3240
static constexpr int MAX_NODES = 3240;
// Use dynamic allocation to avoid static initialization issues
static SudokuDLX::Node* g_node_buffer = nullptr;
static int g_node_count = 0;
static bool g_buffer_init = false;

static void init_node_buffer() {
    if (!g_buffer_init) {
        g_node_buffer = new SudokuDLX::Node[MAX_NODES];
        g_buffer_init = true;
    }
}

bool SudokuDLX::solve(const Grid& puzzle, Grid& solution)
{
	// Validate input
	for (int i = 0; i < 81; ++i)
	{
		int v = puzzle[i];
		if (v < 0 || v > 9) return false;
	}

	// Initialize node buffer on first use
	init_node_buffer();

	// Reset node buffer
	g_node_count = 0;

	// Create a dedicated dummy root header (NOT a real constraint column)
	// This fixes the sentinel issue where headers[0] was both a real column AND the list root
	Node* root = &g_node_buffer[g_node_count++];
	root->constraint_id = -1;
	root->size = 0;
	root->up = root->down = root;
	root->left = root->right = root;

	// Create column headers (324 real constraint columns)
	Node* headers[COLS] = {};
	for (int i = 0; i < COLS; ++i)
	{
		Node* node = &g_node_buffer[g_node_count++];
		headers[i] = node;
		node->constraint_id = i;
		node->size = 0;
		node->up = node->down = node;
	}

	// Link all headers into circular list with root as sentinel
	// root <-> headers[0] <-> headers[1] <-> ... <-> headers[323] <-> root
	root->right = headers[0];
	root->left = headers[COLS - 1];
	headers[0]->left = root;
	headers[COLS - 1]->right = root;
	for (int i = 0; i < COLS - 1; ++i)
	{
		headers[i]->right = headers[i + 1];
		headers[i + 1]->left = headers[i];
	}

	buildMatrix(puzzle, headers);

	// Fixed buffer for solution rows (max 81)
	int solution_rows[81];
	int solution_count = 0;

	// Pass root to search instead of headers array
	if (search(root, solution_rows, solution_count))
	{
		decodeSolution(solution_rows, solution_count, solution);
		return true;
	}

	return false;
}

void SudokuDLX::buildMatrix(const Grid& puzzle, Node* headers[COLS])
{
	// For each possible placement (r, c, d)
	for (int r = 0; r < 9; ++r)
	{
		for (int c = 0; c < 9; ++c)
		{
			for (int d = 1; d <= 9; ++d)
			{
				// If puzzle has a given, only allow that digit
				if (puzzle[idx(r, c)] != 0 && puzzle[idx(r, c)] != d)
					continue;

				int row_id = r * 81 + c * 9 + (d - 1);
				int b = boxOf(r, c);

				// Four constraints for this placement
				int cols[4] = {
					cellCol(r, c),      // cell (r,c) filled
					rowCol(r, d),       // row r has digit d
					colCol(c, d),       // col c has digit d
					boxCol(b, d)        // box b has digit d
				};

				Node* first = nullptr;
				Node* prev = nullptr;

				for (int ci = 0; ci < 4; ++ci)
				{
					int col_idx = cols[ci];
					Node* node = &g_node_buffer[g_node_count++];
					node->row_id = row_id;
					node->constraint_id = col_idx;
					node->column = headers[col_idx];

					// Link vertically (at bottom of column)
					node->up = headers[col_idx]->up;
					node->down = headers[col_idx];
					headers[col_idx]->up->down = node;
					headers[col_idx]->up = node;
					headers[col_idx]->size++;

					// Link horizontally
					if (first == nullptr)
					{
						first = node;
						prev = node;
						node->left = node->right = node;
					}
					else
					{
						node->left = prev;
						node->right = first;
						prev->right = node;
						first->left = node;
						prev = node;
					}
				}
			}
		}
	}
}

void SudokuDLX::cover(Node* c)
{
	// Remove column header from horizontal list
	c->right->left = c->left;
	c->left->right = c->right;

	// Remove all rows in this column from other columns
	for (Node* i = c->down; i != c; i = i->down)
	{
		for (Node* j = i->right; j != i; j = j->right)
		{
			j->down->up = j->up;
			j->up->down = j->down;
			j->column->size--;
		}
	}
}

void SudokuDLX::uncover(Node* c)
{
	// Restore rows in reverse order
	for (Node* i = c->up; i != c; i = i->up)
	{
		for (Node* j = i->left; j != i; j = j->left)
		{
			j->column->size++;
			j->down->up = j;
			j->up->down = j;
		}
	}

	// Restore column header to horizontal list
	c->right->left = c;
	c->left->right = c;
}

bool SudokuDLX::search(Node* root, int* solution_rows, int& solution_count, int depth)
{
	// If root points to itself, all columns covered = solved
	if (root->right == root)
	{
		return true;
	}

	// Choose column with minimum size (Knuth's S heuristic)
	Node* best_col = nullptr;
	int min_size = INT_MAX;

	for (Node* c = root->right; c != root; c = c->right)
	{
		if (c->size < min_size)
		{
			min_size = c->size;
			best_col = c;

			if (min_size == 0)
				return false; // dead end

			if (min_size == 1)
				break; // optimal
		}
	}

	if (!best_col || min_size == 0)
		return false;

	cover(best_col);

	// Try each row in this column
	for (Node* r = best_col->down; r != best_col; r = r->down)
	{
		solution_rows[solution_count++] = r->row_id;

		// Cover all other columns in this row
		for (Node* j = r->right; j != r; j = j->right)
		{
			cover(j->column);
		}

		if (search(root, solution_rows, solution_count, depth + 1))
			return true;

		// Backtrack
		--solution_count;
		for (Node* j = r->left; j != r; j = j->left)
		{
			uncover(j->column);
		}
	}

	uncover(best_col);
	return false;
}

void SudokuDLX::decodeSolution(const int* solution_rows, int solution_count, Grid& solution)
{
	solution.fill(0);
	for (int i = 0; i < solution_count; ++i)
	{
		int row_id = solution_rows[i];
		int r = row_id / 81;
		int c = (row_id % 81) / 9;
		int d = (row_id % 9) + 1;
		solution[idx(r, c)] = d;
	}
}

bool SudokuDLX::validate(const Grid& grid)
{
	// Check rows
	for (int r = 0; r < 9; ++r)
	{
		uint16_t seen = 0;

		for (int c = 0; c < 9; ++c)
		{
			int v = grid[idx(r, c)];

			if (v < 1 || v > 9)
				return false;

			if (seen & (1 << v))
				return false;

			seen |= 1 << v;
		}
	}

	// Check columns
	for (int c = 0; c < 9; ++c)
	{
		uint16_t seen = 0;

		for (int r = 0; r < 9; ++r)
		{
			int v = grid[idx(r, c)];

			if (seen & (1 << v))
				return false;

			seen |= 1 << v;
		}
	}

	// Check boxes
	for (int br = 0; br < 3; ++br)
	{
		for (int bc = 0; bc < 3; ++bc)
		{
			uint16_t seen = 0;

			for (int r = 0; r < 3; ++r)
			{
				for (int c = 0; c < 3; ++c)
				{
					int v = grid[idx(br * 3 + r, bc * 3 + c)];

					if (seen & (1 << v))
						return false;

					seen |= 1 << v;
				}
			}
		}
	}

	return true;
}

void SudokuDLX::Draw(const Grid& grid, bool draw_start)
{
	(void)draw_start; // unused for DLX, but kept for API compatibility

	std::cout << "+-------+-------+-------+\n";
	for (int r = 0; r < 9; ++r) {
		if (r % 3 == 0 && r != 0) {
			std::cout << "+-------+-------+-------+\n";
		}
		std::cout << "| ";
		for (int c = 0; c < 9; ++c) {
			if (c % 3 == 0 && c != 0) {
				std::cout << "| ";
			}
			int v = grid[idx(r, c)];
			if (v == 0) std::cout << ". ";
			else std::cout << v << ' ';
		}
		std::cout << "|\n";
	}
	std::cout << "+-------+-------+-------+\n";
}

