41	namespace SudokuAVX2
42	{
43	    // 16 x 16-bit lanes in a 256-bit register
44	    static constexpr int LANES = 16;
45	    static constexpr Mask ALL_DIGITS = 0x3FE; // bits 1-9 set
46	
47	    // Broadcast a 16-bit mask to all 16 lanes
48	    inline __m256i broadcast_mask(Mask m)
49	    {
50	        return _mm256_set1_epi16(static_cast<short>(m));
51	    }
52	
53	    // Load 16 cell candidates (unaligned, 16 * 2 = 32 bytes)
54	    inline __m256i load_candidates(const Mask* ptr)
55	    {
56	        return _mm256_loadu_si256(reinterpret_cast<const __m256i*>(ptr));
57	    }
58	
59	    // Store 16 cell candidates
60	    inline void store_candidates(Mask* ptr, __m256i val)
61	    {
62	        _mm256_storeu_si256(reinterpret_cast<__m256i*>(ptr), val);
63	    }
64	
65	    // Vectorized popcount for 16 x 16-bit values using nibble lookup table
66	    // Returns popcount for each 16-bit lane in lower 8 bits of each 16-bit lane
67	    inline __m256i popcount_epi16(__m256i x)
68	    {
69	        // Split each 16-bit lane into 4 nibbles (4 bits each)
70	        // Use 16-entry lookup table (popcount for 0-15) duplicated across 256-bit lanes
71	        const __m256i popcnt_lut = _mm256_setr_epi8(
72	            0,1,1,2,1,2,2,3,1,2,2,3,2,3,3,4,  // lane 0: popcount for 0-15
73	            0,1,1,2,1,2,2,3,1,2,2,3,2,3,3,4   // lane 1: same (shuffle operates per 128-bit lane)
74	        );
75	
76	        // Extract low nibbles of each byte
77	        __m256i nibble_mask = _mm256_set1_epi8(0x0F);
78	        __m256i lo_nibble = _mm256_and_si256(x, nibble_mask);
79	        __m256i hi_nibble = _mm256_and_si256(_mm256_srli_epi16(x, 4), nibble_mask);
80	        __m256i lo2_nibble = _mm256_and_si256(_mm256_srli_epi16(x, 8), nibble_mask);
81	        __m256i hi2_nibble = _mm256_and_si256(_mm256_srli_epi16(x, 12), nibble_mask);
82	
83	        // Lookup popcount for each nibble
84	        __m256i cnt0 = _mm256_shuffle_epi8(popcnt_lut, lo_nibble);
85	        __m256i cnt1 = _mm256_shuffle_epi8(popcnt_lut, hi_nibble);
86	        __m256i cnt2 = _mm256_shuffle_epi8(popcnt_lut, lo2_nibble);
87	        __m256i cnt3 = _mm256_shuffle_epi8(popcnt_lut, hi2_nibble);
88	
89	        // Sum all 4 nibbles per 16-bit lane
90	        __m256i sum = _mm256_add_epi8(cnt0, cnt1);
91	        sum = _mm256_add_epi8(sum, cnt2);
92	        sum = _mm256_add_epi8(sum, cnt3);
93	
94	        // Mask to keep only low byte of each 16-bit lane (popcount fits in 4 bits max=9)
95	        return _mm256_and_si256(sum, _mm256_set1_epi16(0x00FF));
96	    }
97	
98	    // Check which lanes have exactly 1 candidate (naked singles)
99	    // Returns mask where each 16-bit lane is 0xFFFF if exactly 1 bit set, 0 otherwise
100	    inline __m256i naked_singles_mask(__m256i candidates)
101	    {
102	        // (candidates & (candidates - 1)) == 0 && candidates != 0
103	        __m256i dec = _mm256_sub_epi16(candidates, _mm256_set1_epi16(1));
104	        __m256i and_result = _mm256_and_si256(candidates, dec);
105	        __m256i is_zero = _mm256_cmpeq_epi16(and_result, _mm256_setzero_si256());
106	        __m256i non_zero = _mm256_cmpgt_epi16(candidates, _mm256_setzero_si256());
107	        return _mm256_and_si256(is_zero, non_zero);
108	    }
109	
110	    // Clear a specific digit mask from all candidates (vectorized)
111	    // candidates &= ~mask
112	    inline __m256i clear_digit(__m256i candidates, Mask digit_mask)
113	    {
114	        __m256i mask = broadcast_mask(~digit_mask);
115	        return _mm256_and_si256(candidates, mask);
116	    }
117	
118	    // Compute candidates for 16 cells with same row/col/box (rare case)
119	    // More commonly: compute for cells in same row (different cols, same row mask)
120	    inline __m256i compute_candidates_row(__m256i row_mask, __m256i col_masks, __m256i box_masks)
121	    {
122	        __m256i combined = _mm256_or_si256(_mm256_or_si256(row_mask, col_masks), box_masks);
123	        __m256i all_digits = broadcast_mask(ALL_DIGITS);
124	        return _mm256_andnot_si256(combined, all_digits);
