130	    {
131	        min_count = 10;
132	        int best_idx = -1;
133	
134	        // Process 16 at a time
135	        int i = 0;
136	        for (; i + LANES <= count; i += LANES) {
137	            __m256i vec = load_candidates(&candidates[i]);
138	            __m256i popcnts = popcount_epi16(vec);
139	
140	            // Extract popcounts and find minimum among non-zero candidates
141	            alignas(32) unsigned char counts[LANES];
142	            _mm256_storeu_si256(reinterpret_cast<__m256i*>(counts), popcnts);
143	
144	            for (int j = 0; j < LANES; ++j) {
145	                int c = counts[j];
146	                if (c > 0 && c < min_count) {
147	                    min_count = c;
148	                    best_idx = i + j;
149	                    if (c <= 1) return best_idx;
150	                }
151	            }
152	        }
153	
154	        // Scalar tail
155	        for (; i < count; ++i) {
156	            if (candidates[i] != 0) {
157	                int c = popcount(candidates[i]);
158	                if (c < min_count) {
159	                    min_count = c;
160	                    best_idx = i;
161	                    if (c <= 1) return best_idx;
162	                }
163	            }
164	        }
165	
166	        return best_idx;
167	    }
