319			// Direct load from member arrays (unaligned is fine for AVX2)
320			__m256i vec_cand = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(&_cell_candidates[base]));
321			__m256i vec_sol = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(&_solution[base]));
322	
323			// Mask out filled cells (set candidates to 0 where solution != 0)
324			__m256i sol_zero = _mm256_cmpeq_epi16(vec_sol, _mm256_setzero_si256());
325			vec_cand = _mm256_and_si256(vec_cand, sol_zero);
326	
327			// For partial final chunk, zero out of bounds lanes
328			if (process < 16) {
329				__m256i mask = _mm256_setr_epi16(
330					(process > 0) ? -1 : 0, (process > 1) ? -1 : 0, (process > 2) ? -1 : 0, (process > 3) ? -1 : 0,
331					(process > 4) ? -1 : 0, (process > 5) ? -1 : 0, (process > 6) ? -1 : 0, (process > 7) ? -1 : 0,
332					(process > 8) ? -1 : 0, (process > 9) ? -1 : 0, (process > 10) ? -1 : 0, (process > 11) ? -1 : 0,
333					(process > 12) ? -1 : 0, (process > 13) ? -1 : 0, (process > 14) ? -1 : 0, (process > 15) ? -1 : 0
334				);
335				vec_cand = _mm256_and_si256(vec_cand, mask);
336			}
337	
338			// Compute popcounts (each 16-bit lane has popcount in low 8 bits)
339			__m256i popcnts = SudokuAVX2::popcount_epi16(vec_cand);
340	
341			// Extract low bytes (popcount per lane) - 16 bytes total
342			alignas(32) unsigned char counts[16];
343			__m256i popcnts_bytes = _mm256_shuffle_epi8(
344				popcnts,
345				_mm256_setr_epi8(
346					0, 2, 4, 6, 8, 10, 12, 14,  // even indices = low bytes of lanes 0-7
347					16, 18, 20, 22, 24, 26, 28, 30, // even indices = low bytes of lanes 8-15
348					-1,-1,-1,-1,-1,-1,-1,-1,
349					-1,-1,-1,-1,-1,-1,-1,-1
350				)
351			);
352			_mm256_storeu_si256(reinterpret_cast<__m256i*>(counts), popcnts_bytes);
353	
354			for (int j = 0; j < process; ++j) {
355				int c = counts[j];
356				// Only flag contradiction for EMPTY cells (solution == 0)
357				// Filled cells have c == 0 after masking but are not contradictions
358				if (c == 0 && _solution[base + j] == 0) {
359					// Contradiction: empty cell with no candidates -> fail fast
360					return base + j;
361				}
362				if (c > 0 && c < min_count) {
363					min_count = c;
364					best_idx = base + j;
365					if (c <= 1) return best_idx;
366				}
367			}
368		}
369	
370		return best_idx;
371	#else
372		int bestCell = -1;
373		int minCandidates = 10;
374	
375		for (int i = 0; i < 81; ++i) {
376			if (_solution[i] == 0) {
377				Mask candidates = _cell_candidates[i];
378				int count = _countBits(candidates);
379				if (count < minCandidates) {
380					minCandidates = count;
381					bestCell = i;
382					if (count <= 1) return bestCell;
383				}
384			}
385		}
386		return bestCell;
387	#endif
