197	bool Sudoku::solve()
198	{
199		for (int i = 0; i < 81; ++i) _solution[i] = _grid[i];
200		std::fill(std::begin(_rows), std::end(_rows), 0);
201		std::fill(std::begin(_cols), std::end(_cols), 0);
202		std::fill(std::begin(_boxes), std::end(_boxes), 0);
203	
204		// Initialize masks from givens with validation
205		for (int r = 0; r < N; ++r) {
206			for (int c = 0; c < N; ++c) {
207				int num = _solution[idx(r, c)];
208				if (num != 0) {
209					// Validate input range
210					if (num < 1 || num > 9) return false;
211					Mask m = DIGIT_MASK[num];
212					// Check for conflicting givens (same digit already in row/col/box)
213					if ((_rows[r] & m) || (_cols[c] & m) || (_boxes[BOX_OF[idx(r, c)]] & m))
214						return false;
215					_rows[r] |= m;
216					_cols[c] |= m;
217					_boxes[BOX_OF[idx(r, c)]] |= m;
218				}
219			}
220		}
221	
222		// Initialize cell candidates
223		for (int r = 0; r < N; ++r) {
224			for (int c = 0; c < N; ++c) {
225				int i = idx(r, c);
226				if (_solution[i] == 0) {
227					_cell_candidates[i] = _getCandidates(r, c);
228				} else {
229					_cell_candidates[i] = 0;
230				}
231			}
232		}
233	
234		// Apply constraint propagation before search
235		if (!_propagate())
236			return false; // contradiction from givens
237	
238		_solved = _solveRecursive(0);
239		return _solved;
240	}
