390	// Constraint propagation techniques
391	// Returns false if contradiction detected (empty cell with no candidates)
392	bool Sudoku::_propagate()
393	{
394		bool progress = true;
395		while (progress) {
396			progress = false;
397			if (!_nakedSingles())
398				return false; // contradiction
399			if (!_hiddenSingles())
400				return false; // contradiction
401		}
402		return true;
403	}
