405	// Naked singles: cell with only 1 candidate
406	// Returns false if contradiction (empty cell with 0 candidates after update)
407	bool Sudoku::_nakedSingles()
408	{
409		bool progress = false;
410	
411	#if SUDOKU_AVX2
412		// Vectorized: find all naked singles in chunks of 16
413		// Direct load from member arrays (no gather/scatter overhead)
414		for (int base = 0; base < 81; base += 16) {
415			int remaining = 81 - base;
416			int process = (remaining >= 16) ? 16 : remaining;
417	
418			// Direct load from member arrays (unaligned is fine for AVX2)
419			__m256i vec_cand = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(&_cell_candidates[base]));
420			__m256i vec_sol = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(&_solution[base]));
421	
422			// Mask out filled cells
423			__m256i sol_zero = _mm256_cmpeq_epi16(vec_sol, _mm256_setzero_si256());
424			vec_cand = _mm256_and_si256(vec_cand, sol_zero);
425	
426			// For partial final chunk, zero out of bounds lanes
427			if (process < 16) {
428				__m256i mask = _mm256_setr_epi16(
429					(process > 0) ? -1 : 0, (process > 1) ? -1 : 0, (process > 2) ? -1 : 0, (process > 3) ? -1 : 0,
430					(process > 4) ? -1 : 0, (process > 5) ? -1 : 0, (process > 6) ? -1 : 0, (process > 7) ? -1 : 0,
431					(process > 8) ? -1 : 0, (process > 9) ? -1 : 0, (process > 10) ? -1 : 0, (process > 11) ? -1 : 0,
432					(process > 12) ? -1 : 0, (process > 13) ? -1 : 0, (process > 14) ? -1 : 0, (process > 15) ? -1 : 0
433				);
434				vec_cand = _mm256_and_si256(vec_cand, mask);
435			}
436	
437			// Find naked singles: exactly 1 bit set
438			__m256i singles_mask = SudokuAVX2::naked_singles_mask(vec_cand);
439	
440			// Extract which lanes are naked singles (16-bit mask per lane: 0xFFFF or 0)
441			alignas(32) uint16_t mask_arr[16];
442			_mm256_storeu_si256(reinterpret_cast<__m256i*>(mask_arr), singles_mask);
443	
444			for (int j = 0; j < process; ++j) {
445				if (mask_arr[j]) {
446					int i = base + j;
447					Mask candidates = _cell_candidates[i];
448					int num = ctz(candidates);
449					int r = i / 9, c = i % 9;
450					_solution[i] = num;
451					Mask m = DIGIT_MASK[num];
452					_rows[r] |= m;
453					_cols[c] |= m;
454					_boxes[BOX_OF[i]] |= m;
455					_cell_candidates[i] = 0;
456					progress = true;
457				}
458			}
459		}
460	#else
461		for (int i = 0; i < 81; ++i) {
462			if (_solution[i] == 0) {
463				Mask candidates = _cell_candidates[i];
464				if (candidates && (candidates & (candidates - 1)) == 0) {
465					int num = ctz(candidates);
466					int r = i / 9, c = i % 9;
467					_solution[i] = num;
468					Mask m = DIGIT_MASK[num];
469					_rows[r] |= m;
470					_cols[c] |= m;
471					_boxes[BOX_OF[i]] |= m;
472					_cell_candidates[i] = 0;
473					progress = true;
474				}
475			}
476		}
477	#endif
478	
479		if (progress) {
480			for (int r = 0; r < N; ++r) {
481				for (int c = 0; c < N; ++c) {
482					_updateCandidates(r, c);
483				}
484			}
485		}
486	
487		// Check for contradictions: empty cell with 0 candidates
488		for (int i = 0; i < 81; ++i) {
489			if (_solution[i] == 0 && _cell_candidates[i] == 0)
490				return false;
491		}
492		return true;
493	}
