495	// Hidden singles: digit appears only once in a house
496	// Returns false if contradiction (empty cell with 0 candidates after update)
497	bool Sudoku::_hiddenSingles()
498	{
499		bool progress = false;
500	
501		// Collect hidden singles: (cell, digit)
502		struct HiddenSingle { int cell; int digit; };
503		HiddenSingle singles[27]; // max 27 (9 rows + 9 cols + 9 boxes)
504		int singles_count = 0;
505	
506		// Check rows
507		for (int r = 0; r < N; ++r) {
508			for (int d = 1; d <= 9; ++d) {
509				Mask m = DIGIT_MASK[d];
510				if (_rows[r] & m) continue;
511				int count = 0, last_c = -1;
512				for (int c = 0; c < N; ++c) {
513					int i = idx(r, c);
514					if (_solution[i] == 0 && (_cell_candidates[i] & m)) {
515						count++;
516						last_c = c;
517					}
518				}
519				if (count == 1) {
520					int i = idx(r, last_c);
521					singles[singles_count++] = {i, d};
522				}
523			}
524		}
525	
526		// Check columns
527		for (int c = 0; c < N; ++c) {
528			for (int d = 1; d <= 9; ++d) {
529				Mask m = DIGIT_MASK[d];
530				if (_cols[c] & m) continue;
531				int count = 0, last_r = -1;
532				for (int r = 0; r < N; ++r) {
533					int i = idx(r, c);
534					if (_solution[i] == 0 && (_cell_candidates[i] & m)) {
535						count++;
536						last_r = r;
537					}
538				}
539				if (count == 1) {
540					int i = idx(last_r, c);
541					singles[singles_count++] = {i, d};
542				}
543			}
544		}
545	
546		// Check boxes - use precomputed BOX_CELLS for 9x speedup
547		for (int b = 0; b < 9; ++b) {
548			for (int d = 1; d <= 9; ++d) {
549				Mask m = DIGIT_MASK[d];
550				if (_boxes[b] & m) continue;
551				int count = 0, last_cell = -1;
552				// Iterate only 9 cells in this box instead of all 81
553				for (int k = 0; k < 9; ++k) {
554					int i = BOX_CELLS[b][k];
555					if (_solution[i] == 0 && (_cell_candidates[i] & m)) {
556						count++;
557						last_cell = i;
558					}
559				}
560				if (count == 1) {
561					singles[singles_count++] = {last_cell, d};
562				}
563			}
564		}
565	
566		// Place all collected hidden singles at once (using original candidate state)
567		for (int s = 0; s < singles_count; ++s) {
568			int i = singles[s].cell;
569			int d = singles[s].digit;
570			if (_solution[i] != 0) continue; // already filled by earlier single in this batch
571			Mask m = DIGIT_MASK[d];
572			_solution[i] = d;
573			_rows[i / 9] |= m;
574			_cols[i % 9] |= m;
575			_boxes[BOX_OF[i]] |= m;
576			_cell_candidates[i] = 0;
577			progress = true;
578		}
579	
580		if (progress) {
581			for (int r = 0; r < N; ++r) {
582				for (int c = 0; c < N; ++c) {
583					_updateCandidates(r, c);
584				}
585			}
586		}
587	
588		// Check for contradictions: empty cell with 0 candidates
589		for (int i = 0; i < 81; ++i) {
590			if (_solution[i] == 0 && _cell_candidates[i] == 0)
591				return false;
592		}
593		return true;
594	}
