bool Sudoku::_solveRecursive(int depth)
{
	// Safety: limit recursion depth to prevent stack overflow
	if (depth > 81) return false;

	int cell = _findBestCell();
	if (cell == -1) {
		// No cell with candidates found - check if solved or contradiction
		for (int i = 0; i < 81; ++i) {
			if (_solution[i] == 0) return false; // empty cell with 0 candidates = contradiction
		}
		return true; // completely filled = solved
	}

	Mask candidates = _cell_candidates[cell];
	if (candidates == 0)
		return false;

	int row = cell / 9;
	int col = cell % 9;
	int b = BOX_OF[cell];

	// Try each candidate (use member arrays to avoid stack overflow)
	while (candidates) {
		Mask m = candidates & -candidates;
		int num = ctz(m);
		candidates &= candidates - 1;

		// Place digit
		_solution[cell] = num;
		_rows[row] |= m;
		_cols[col] |= m;
		_boxes[b] |= m;

		// Save full state before propagation (propagation can modify many cells)
		for (int i = 0; i < 81; ++i) {
			_saved_candidates[i] = _cell_candidates[i];
			_saved_solution[i] = _solution[i];
		}
		for (int i = 0; i < 9; ++i) {
			_saved_rows[i] = _rows[i];
			_saved_cols[i] = _cols[i];
			_saved_boxes[i] = _boxes[i];
		}

		// Recompute ALL candidates from updated masks (not just peers)
	// This ensures _propagate() works with fresh candidate data
		for (int r = 0; r < N; ++r) {
			for (int c = 0; c < N; ++c) {
				_updateCandidates(r, c);
			}
		}

		// Apply constraint propagation after placement
		if (_propagate()) {
			if (_solveRecursive(depth + 1))
				return true;
		}

		// Backtrack - restore full state
		for (int i = 0; i < 81; ++i) {
			_cell_candidates[i] = _saved_candidates[i];
			_solution[i] = _saved_solution[i];
		}
		for (int i = 0; i < 9; ++i) {
			_rows[i] = _saved_rows[i];
			_cols[i] = _saved_cols[i];
			_boxes[i] = _saved_boxes[i];
		}
	}

	return false;
}

