bool Sudoku::_solveRecursive(int depth)
{
	// Safety: limit recursion depth to prevent stack overflow
	if (depth > 81) {
		std::cerr << "DEBUG: depth limit exceeded: " << depth << std::endl;
		return false;
	}

	std::cerr << "DEBUG: _solveRecursive depth=" << depth << std::endl;

	int cell = _findBestCell();
	std::cerr << "DEBUG: _findBestCell returned cell=" << cell << std::endl;
	if (cell == -1) {
		// No cell with candidates found - check if solved or contradiction
		for (int i = 0; i < 81; ++i) {
			if (_solution[i] == 0) {
				std::cerr << "DEBUG: contradiction - empty cell at " << i << std::endl;
				return false; // empty cell with 0 candidates = contradiction
			}
		}
		std::cerr << "DEBUG: solved!" << std::endl;
		return true; // completely filled = solved
	}

	if (cell < 0 || cell >= 81) {
		std::cerr << "DEBUG: INVALID cell index: " << cell << std::endl;
		return false;
	}

	Mask candidates = _cell_candidates[cell];
	std::cerr << "DEBUG: cell=" << cell << " candidates=" << std::hex << candidates << std::dec << std::endl;
	if (candidates == 0) {
		std::cerr << "DEBUG: cell=" << cell << " has 0 candidates!" << std::endl;
		return false;
	}

	int row = cell / 9;
	int col = cell % 9;
	int b = BOX_OF[cell];

	// Try each candidate (use local std::array - heap allocated for large arrays)
	while (candidates) {
		Mask m = candidates & -candidates;
		int num = ctz(m);
		candidates &= candidates - 1;

		std::cerr << "DEBUG: trying cell=" << cell << " num=" << num << std::endl;

		// Place digit
		_solution[cell] = num;
		_rows[row] |= m;
		_cols[col] |= m;
		_boxes[b] |= m;

		// Save full state before propagation (local std::array - heap allocated)
		std::array<Mask, 81> saved_candidates;
		std::array<uint16_t, 81> saved_solution;
		std::array<Mask, 9> saved_rows, saved_cols, saved_boxes;

		for (int i = 0; i < 81; ++i) {
			saved_candidates[i] = _cell_candidates[i];
			saved_solution[i] = _solution[i];
		}
		for (int i = 0; i < 9; ++i) {
			saved_rows[i] = _rows[i];
			saved_cols[i] = _cols[i];
			saved_boxes[i] = _boxes[i];
		}

		// Recompute ALL candidates from updated masks (not just peers)
		// This ensures _propagate() works with fresh candidate data
		std::cerr << "DEBUG: recomputing candidates..." << std::endl;
		for (int r = 0; r < N; ++r) {
			for (int c = 0; c < N; ++c) {
				_updateCandidates(r, c);
			}
		}
		std::cerr << "DEBUG: candidates recomputed" << std::endl;

